-- Backfill Date Quoted (field f_quoted) on Geo Bids bids that have none: the date the bid last moved into Quoted (from its history), else its done date if it is in Quoted now. Then copies in Geo Follow-Up get the same date from their original. Logs a history entry on each Geo Bids bid. Safe to run more than once.
update wf_bids b set fields = jsonb_set(coalesce(b.fields,'{}'::jsonb), '{f_quoted}', to_jsonb(x.d)), history = coalesce(b.history,'[]'::jsonb) || jsonb_build_array(jsonb_build_object('by','Automation','at',(extract(epoch from now())*1000)::bigint,'field','Date Quoted','from','None','to',to_char(x.d::date,'Mon FMDD, YYYY'))) from (select b2.id, coalesce((select to_char(to_timestamp(max((h->>'at')::bigint)/1000.0) at time zone 'America/Denver','YYYY-MM-DD') from jsonb_array_elements(coalesce(b2.history,'[]'::jsonb)) h where h->>'field'='Status' and lower(h->>'to')='quoted'), case when lower(z.st->>'name')='quoted' then b2.done_at::text end) as d from wf_bids b2 join wf_spaces s on s.id=b2.space_id left join lateral (select e from jsonb_array_elements(s.statuses) e where e->>'id'=b2.status limit 1) z(st) on true where s.key='GB' and s.division_id in (select id::text from divisions where lower(name)='geo') and coalesce(b2.fields->>'f_quoted','')='') x where b.id=x.id and x.d is not null returning b.num, b.title, x.d as date_quoted;
update wf_bids c set fields = jsonb_set(coalesce(c.fields,'{}'::jsonb), '{f_quoted}', o.fields->'f_quoted') from wf_bids o join wf_spaces so on so.id=o.space_id where c.origin_bid_id=o.id and so.key='GB' and so.division_id in (select id::text from divisions where lower(name)='geo') and coalesce(c.fields->>'f_quoted','')='' and coalesce(o.fields->>'f_quoted','')<>'' returning c.num, c.title, c.fields->>'f_quoted' as date_quoted;
